    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        if message:
            func.__doc__ = func.__doc__.replace(func.__name__, '{} :: {}'.format(message, func.__name__))
