def parse_version(s: str) -> tuple[int, ...]:
    prefixes = ["v", "V", "V1", "V2", "v1", "v2"]
    for c in prefixes:
        if c in s.lstrip():
            return tuple(map(int, s.removeprefix(c).split(".")))
    return tuple(map(int, s.split(".")))

