def extostr(cls, e, max_level=30, max_path_level=5):
    tb = sys.exc_info()[2]
    tbinfo = traceback.extract_tb(tb)
    path, line, name, src = '', '', '', None
    level = 0
    while tb and level <= max_level:
        path, line, name, src = tbinfo[level]
        tb = tb.tb_next
        level += 1

    retd = {
        'type': str(e.__class__.__name__),
        'message': str(e),
        'file': path,
        'line': line,
        'name': name,
        'src': src
    }

    if isinstance(e, s_exc.SynErr):
        retd['syn:err'] = e.errinfo

    return (e.__class__.__name__, retd)

