def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """

    if isinstance(d1, dict) and isinstance(d2, dict) and level == -1:
        # perform a deep copy of d1 unless it's already a dict instance
        if not isinstance(d1, dict):
            d1 = d1.copy()

        for key, value in d1.items():
            if key in d2 and level != -1 or key not in d2:
                # if a key is present both in d1 and d2 but has different values,
                # it is included into the difference
                if isinstance(value, dict) and isinstance(d2.get(key), dict):
                    d1[key] = difference(value, d2[key], level - 1)
                else:
                    d1[key] = value
        return d1
    else:
        return {}

def difference(d1, d2, level=-1):
    if level == -1:
        return (d1 - d2) | (d1 & d2)
    if d1 == d2:
        return {}
    elif isinstance(d1, Mapping) and isinstance(d2, Mapping):
        diff = {}
        for key in d1.keys() & d2.keys():
            sub_diff = difference(d1[key], d2[key], level - 1)
            if sub_diff:
                diff[key] = sub_diff
            elif d1[key] != d2[key]:
                diff[key] = d2[key]
        for key in d1.keys() - d2.keys():
            diff[key] = d1[key]
        for key in d2.keys() - d1.keys():
            diff[key] = d2[key]
        return diff
    else:
        return {}

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level < 0:
        return d1.copy()
    if level == 0:
        diff_dict = {}
        for key in d1.keys():
            if key not in d2 and d1[key] != d2.get(key, None):
                diff_dict[key] = d1[key]
        for key in d2.keys():
            if key not in d1:
                diff_dict[key] = d2[key]
        return diff_dict
    diff_dict = {}
    for key in d1.keys():
        if key in d2:
            if level < 1:
                diff_dict[key] = {}
            diff_dict[key] = difference(d1[key], d2[key], level - 1)
        else:
            diff_dict[key] = d1[key]
    for key in d2.keys():
        if key not in d1:
            diff_dict[key] = d2[key]
    return diff_dict

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """  
    if level == -1:
        return {k: d1[k] for k in d1 if k not in d2}
    return {k: difference(d1[k], d2[k], level - 1)
            for k in d1 if d1[k] is not None and k not in d2}

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.

    """
    if not (isinstance(coord, tuple) and len(coord) == 2):
        raise ValueError("coord must be a tuple of two elements")
    if weight <= 0:
        raise ValueError("weight must be positive")

    minx, miny = self.set_bounds(coord[0])
    maxx, maxy = self.set_bounds(coord[1])
    if coord[0] < minx or coord[0] > maxx:
        return 0
    if coord[1] < miny or coord[1] > maxy:
        return 0

    indexx = int((coord[0] - minx) / self.bin_widths[0])
    indexy = int((coord[1] - miny) / self.bin_heights[1])

    if indexx < 0 or indexx >= len(self.edges[0]) or indexy < 0 or indexy >= len(self.edges[1]):
        return 0

    if self bins is None:
        self.bins = [
            [0] * (len(self.edges[1]) - 1) for _ in range(len(self.edges[0]) - 1)
        ]
    self.bins[indexx][indexy] += weight

    return weight

def _validate_labels(labels: Dict) -> Dict:
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """

    def _validate_value(value, type_check):
        if not isinstance(value, type_check):
            return False
        return True

    messages: List[Dict] = []
    for key in labels:
        if key in labels and not isinstance(key, (str, bytes)):
            messages.append({"key": f"'{key}' is not a string or bytes-like object"})

        if key not in labels and not isinstance(key, str):
            messages.append({"key": f"'{key}' is not a string or bytes-like object"})

        if not isinstance(labels[key], (str, bytes, list)):
            messages.append({"key": f"'{key}' is not a string, bytes-like object or list"})

        if isinstance(labels[key], list):
            for item in labels[key]:
                if not isinstance(item, (str, bytes)):
                    messages.append({"key": f"'{item}' in key '{key}' is not a string or bytes-like object"})

    return messages

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """,

    # Define the regular expressions for each label key
    label_regexes = {
        "key1": r'\bvalid\b',
        "key2": r'\binvalid\b',
        "$$": r'\$',
        True: r'\bTrue\b',
    }

    errors = []
    for label, value in labels.items():
        if not isinstance(value, str):
            errors.append({'[\'%s\']' % label: 'expected string or bytes-like object'})
            continue

        regex_key = f"$__${label}_label_type_regex"
        if regex_key in label_regexes:
            regex = label_regexes[regex_key]
            if not bool(re.match(regex, value)):
                errors.append({'[\'%s\']' % label: f"Label key '{label}' does not match the regex {regex}"})
        else:
            try:
                type_check = value[0]
            except IndexError:
                errors.append({'[\'%s\']' % label: 'expected string or bytes-like object'})
                continue

            if isinstance(type_check, str):
                type_check_regex = '[' + type_check.replace(' ', r'\ ') + ']'
                regex = rf'\b(?:[^{re.escape(label_regexes[label])}]+){type_check_regex}\b'
            else:
                regex = rf'\b(?:[^{re.escape(label_regexes[label])}]+)\b'

            if not bool(re.match(regex, value)):
                errors.append({'[\'%s\']' % label: f"Label key '{label}' does not match the regex {regex}"})

    if errors:
        raise ValidationError(errors)

def _validate_labels(labels: Dict[str, str]):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
