def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    regex_types = {
        "key1": r"^[a-z_]+$/,
        "key2": r"^[0-9]+",
        "$$": r"^[^/]+(?<![/])$",  # This regex allows /[a-zA-Z]/ characters within, but not at the end of the string
        True: "^[01]$",  # This regex only allows 'true' or 'false'
    }

    errors = []
    for key, value in labels.items():
        if isinstance(value, list):
            for key in value:
                if not regex_types.get(key):
                    errors.append({"key": key, "value": f"expected string or bytes-like object"})
        else:
            if not regex_types.get(key):
                errors.append({"key": key, "value": f"expected string or bytes-like object"})

    if errors:
        raise ValidationError(errors)

def _validate_labels(labels: Dict[str, Union[str, List[str], bool, int]]) -> None:
    messages = []
    for label_name in labels:
        try:
            if isinstance(labels[label_name], str):
                validate(instance=labels[label_name], schema=LABEL_REGEXP)
            elif isinstance(labels[label_name], list):
                for value in labels[label_name]:
                    validate(instance=value, schema=LABEL_REGEXP)
            elif not isinstance(labels[label_name], (str, list, bool, int)):
                raise InvalidFormat(f"Invalid type '{type(labels[label_name]).__name__}' for label '{label_name}'")
        except ValidationError as e:
            messages.append({
                f"['{label_name}']": e.message
            })
    if messages:
        raise InvalidFormat(messages)

