    from krake.data.kubernetes import (
        Application as KrakeApp,
        Schema,
        Array,
    )

    # Check if the schema already has a default observer schema
    for resource in app.spec.manifest:
        schema_key = f"{resource.kind}_{resource.metadata.name}"
        if schema_key in app.schema:
            continue

        # Generate the default observer schema for the resource
        keyword_args = get_default_observer_kwargs(resource)
        schema = Schema(
            type=ResourceSchema,
            properties={
                "kind": {"type": "string"},
                "metadata": {"type": "object"},
                "spec": {
                    "type": "object",
                    "properties": {
                        "observers": {
                            "type": "array",
                            "items": {
                                "type": "object",
                                "properties": {
                                    **keyword_args
                                }
                            }
                        }
                    }
                }
            }
        )

        # Add the default observer schema to the application's schema
        app.schema[schema_key] = schema

    # The generated default observer schema for each Kubernetes resource
    return app.schema

