                "properties": {}
            }
            if 'kind' in manifest:
                observer_schema['properties']['apiVersion'] = {
                    "type": "string",
                    "description": f"Applies to resources in {manifest['apiVersion']}"
                }
                observer_schema['properties']['kind'] = {
                    "type": "string",
                    "description": "The kind of kubernetes resource"
                }
            if 'name' in manifest:
                observer_schema['properties']['name'] = {
                    "type": "string",
                    "description": f"Name of the {manifest['kind']}"
                }
            # Add additional properties based on the manifest
            app.spec.defaults.krake.io/configschema[resource] = observer_schema

