def formatmany(self, sql, many_params):
    formatted_sql = sql.replace('%s', '?') if isinstance(sql, str) or isinstance(sql, bytes) else f'?'
    return formatted_sql, [params.values() for params in many_params]

def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]):
        formatted_query = sql
        converted_params = []
        for params in many_params:
            converted_params_data = []
            if self.SQLParams.in_style == 'named':
                converted_params_data = {key: value for key, value in params.items()}
            elif self.SQLParams.in_style == 'ordinal':
                converted_params_data = list(params)
            formatted query = formatted_query.replace('{}', '{}', 1)
            converted_params.append(converted_params_data)
        return formatted_query, converted_params

def formatmany(self, sql: str, many_params: Union[Iterable[Dict[str, Any]], Iterable[Sequence[Any]]]) -> Tuple[str, Union[List[Dict[str, Any]], List[Sequence[Any]]]]:
    def formatter(item):
        if isinstance(item, Mapping):
            keys_value = ['%s=%s' % (key, str(value)) for key, value in item.items()]
            return '(' + ', '.join(keys_value) + ')'
        if isinstance(item, Sequence):
            return '%' * len(item)
        raise TypeError("unsupported type %r" % type(item))

    formatted_sql = sql.replace('%s', '(:n_%s)')
    values = []

    for params in many_params:
        if isinstance(params, Mapping):
            indexed_params = {str(i + 1): value for i, value in enumerate(params.values())}
        elif isinstance(params, Sequence):
            indexed_params = ['%s' % value for value in params]
        else:
            raise TypeError("unsupported type %r" % type(params))

        formatted_params = ','.join(formatter(param) for param in indexed_params)
        values.append(formatted_params)

    return formatted_sql, values

