def get_logical_path_map(self, inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    mapped_paths = {}
    versions_to_process = {version}

    while versions_to_process:
        version = versions_to_process.pop()
        if version in inventory:
            for path, files in inventory[version].items():
                for file_path in files:
                    logical_path = self._resolve_logical_path(file_path)
                    if logical_path in mapped_paths:
                        mapped_paths[logical_path].update(files)
                    else:
                        mapped_paths[logical_path] = set(files)
            versions_to_process.update(inventory[version].keys())

    return mapped_paths

