def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package

    Returns
    -------
    dict
    """
    datas = {}
    for root, _, files in os.walk(folder):
        for f in files:
            if f.endswith('.xml'):
                basename = os.path.splitext(f)[0]
                if basename in datas:
                    datas[basename].append(os.path.join(root, f))
                else:
                    datas[basename] = [os.path.join(root, f)]
    return datas

def _explore_folder(folder):
    """Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    file_data = {}
    for root, dirs, files in os.walk(folder):
        for f in files:
            if f.endswith('.xml'):
                file_path = os.path.join(root, f)
                basename = os.path.splitext(f)[0]
                file_data[basename] = {'file': file_path, 'directory': root}
    return file_data

