def _extract_number_and_supplement_from_issue_element(issue):
    output = []

    # Regular expression to find numbers and supplements
    pattern = r'\b\d+\s*(Suppl|spe| suppl\d+)\b'
    matches = re.findall(pattern, issue)

    for match in matches:
        number, supplement = match.split()
        if supplement == 'Suppl':
            output.append(int(number))
        elif supplement == 'spe':
            output.append(int(number[:-2]))
        elif supplement == 'suppl\d+':
            output.append(int(number[:-2]))
        elif supplement == 'spe2' or supplement == 'spepr' or supplement == 'spe.2':
            output.append(int(number[:-3]))
        elif supplement == 's2':
            output.append(int(number[:-1]))

    return output

