def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

            A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for arg in args:
        # Separate the absorption and negative absorption terms
        absorption_terms = arg.split('(')
        negative_absorption_terms = []
        if len(absorption_terms) >= 2:
            for term in absorption_terms[1:-1]:
                if 'A' in term and 'B' in term:
                    absorption_terms[1] = term.replace('A', '0').replace('B', '0')
                elif 'A' in term and '~A' in term:
                    absorption_terms[1] = term.replace('A', '1').replace('~A', '1')
                elif '~A' in term and 'B' in term:
                    absorption_terms[1] = term.replace('A', '1').replace('~A', '1')
        else:
            absorption_terms = arg.split(' ')
        if absorption_terms and ':' in absorption_terms[-1]:
            absorption_terms[-1] = absorption_terms[-1].split(':')

        # Process each term in absorption and negative absorption
        for term in absorption_terms:
            if 'A' in term and 'B' in term:
                result.append(term)
            elif 'A' in term and '~A' in term:
                result.append(term.replace('A', '1').replace('~A', '1'))
            elif '~A' in term and 'B' in term:
                result.append(term.replace('A', '1').replace('~A', '1'))

        # Combine all terms in absorption and negative absorption
        if negative_absorption_terms:
            result = [term + '|' + abs_term for term, abs_term in zip(result, negative_absorption_terms)]
        else:
            result = [term.replace('|', '&') for term in result]

    return result

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    def absorb_and(x, y):
        return x & y

    def absorb_or(x, y):
        return x | y

    def negate_absorb_and(x, y):
        return x & ~y

    def negate_absorb_or(x, y):
        return x | ~y

    result = []
    for expr in args:
        parts = expr.split('*')
        if len(parts) == 1:
            result.append(expr)
        elif len(parts) == 2:
            if parts[0] == 'absorb':
                op = absorb_and
            elif parts[0] == 'absorb_or':
                op = absorb_or
            elif parts[0] == 'negate_absorb_and':
                op = negate_absorb_and
            elif parts[0] == 'negate_absorb_or':
                op = negate_absorb_or
            else:
                raise ValueError("invalid operation in expression")
            term = parts[1]
            if term.isdigit():
                term = int(term)
            result.append(f"{term}({func(term)({parts[1]})})")
        else:
            raise ValueError("invalid expression Parts")

    return result

