    """
    Call the given command(s).

    :param commands: List of command names to run
    :param args: List of arguments for each command
    :param cwd: Current working directory (optional)
    :param verbose: Whether to print verbose output (optional)
    :param hide_stderr: Whether to hide the standard error (optional)
    :param env: Environment variables to use (optional)
    """
    for cmd, argset in zip(commands, args):
        if verbose:
            print(f"Running command: {cmd} with args: {argset}")
        if cwd:
            os.chdir(cwd)
        if env:
            os.environ.update(env)
        command = subprocess.Popen(cmd, shell=True, args=argset, cwd=cwd, stdout=subprocess.PIPE)
        stdout, stderr = command.communicate()
        if command.returncode != 0:
            if verbose:
                print(f"Command {cmd} failed with return code {command.returncode}")
                print(f"Error: {stderr.decode('utf-8')}")
            if hide_stderr:
                stdout = b""
            if command.returncode != 0 and not hide_stderr:
                sys.exit(command.returncode)
        if verbose:
            print(f"Command {cmd} completed with output: {stdout.decode('utf-8')}")

def run_command(commands: List[str], args: Optional[List] = None, cwd: Optional[str] = None,
                  verbose: bool = False, hide_stderr: bool = False, env: Optional[dict] = None) -> None:
    """Call the given command(s)."""

    if verbose:
        print(f"Running the command: {' '.join(commands + args)}")

    try:
        if args:
            result = subprocess.run(commands + args, cwd=cwd, env=env, check=True,
                                stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        else:
            result = subprocess.run(commands, cwd=cwd, env=env, check=True,
                                stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except subprocess.CalledProcessError as e:
        stderr_output = e.stderr.decode('utf-8').strip()
        if hide_stderr:
            stderr = bytes()  # simulate no output if hide_stderr is True
        else:
            stderr = stderr_output

        if verbose:
            print(f"Error details: {stderr_output}")

        raise ProgramError(f"Command failed: {e}") from e
    else:
        if verbose:
            output = result.stdout.decode('utf-8').strip()
            print(f"Command output: {output}")

class VersioneerConfig:
    def __init__(self):
        self.default_config_filepath = Path2(os.path.dirname(__file__), _DEAFULT_CONFIG_FILENAME)
        self.ini_filepath = get_ini_filepath()
        self.config = self._read_and_convert(self.default_config_filepath, all_values=True)
        if not self.ini_filepath:
            self.ini_filepath = get_user_ini_filepath()
            with self.default_config_filepath.open("r") as infile:
                with self.ini_filepath.open("w") as outfile:
                    outfile.write(infile.read())
            print("\n*************************************************************")
            print("Default config file was created into your home:")
            print("\t%s" % self.ini_filepath)
            print("Change it for your needs ;)")
            print("*************************************************************\n")
        config.update(self._read_and_convert(self.ini_filepath, all_values=False))
        self.config = _load_options(parser)
        logging.debug('Config loaded: {}'.format(self.default_config_filepath))

    @classmethod
    def _read_and_convert(cls, filepath, all_values):
        config = {}
        with filepath.open("r") as f:
            parser = configparser.ConfigParser()
            parser.read_file(f)
            for section in parser.sections():
                for key, value in parser.items(section):
                    config[key] = value
            return config if all_values else {k: v for k, v in config.items() if not v.startswith("!")}

    @classmethod
    def _load_option(cls, section, option):
        return cls._read_and_convert(Path2(section), all_values=True).get(option, None)

    @classmethod
    def get_value(cls, *args, **kwargs):
        """Get from config object by exposing Config.get_value method."""
        if _config is None:
            raise ValueError('configuration not set; must run figgypy.set_config first')
        return _config.get_value(*args, **kwargs)

