def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    store = self._get_storage()
    hierarchy = store.getHierarchy()
    root = hierarchy.getRoot()
    objects_to_check = [root]
    num_objects = 0
    good_objects = 0

    for obj in objects_to_check:
        num_objects += 1
        if validate_objects:
            errors = obj.getAllErrors()
            if errors:
                for error in errors:
                    print("Cannot create new object '{0}' with errors: '{1}'".format(obj.getMetadata(), error))
                    continue
                good_objects += 1

        if check_digests:
            digest = obj.calculateDigest()
            if digest != obj.getExpectedDigest():
                print("Database digest for the hierarchy object '{0}' destroyed".format(obj.getMetadata()))
            else:
                good_objects += 1

        if show_warnings:
            warn = obj.calculateWarning()
            if warn:
                print("Database warning for the hierarchy object '{0}' is: '{1}'".format(obj.getMetadata(), warn))

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    if not self._storage_root_repo:
        raise ValueError('Storage root repository is not set')

    # Perform validation
    good_objects = 0
    num_objects = sum(self._storage_root_repo.list_root_object_ids())
    for obj_id in self._storage_root_repo.list_root_object_ids():
        if validate_objects:
            obj = self._storage_root_repo.get_object(obj_id)
            if check_digests:
                obj.digest()
            self._validate_object(obj)
            good_objects += 1

    if show_warnings:
        for obj_id in self._storage_root_repo.list_root_object_ids():
            obj = self._storage_root_repo.get_object(obj_id)
            print(f'Found object {obj_id}, {self._validate_object(obj)}')

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects: bool = True, check_digests: bool = True, show_warnings: bool = False) -> Union[int, int]:
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        if validate_objects:
            try:
                # Implementation to validate storage root hierarchy objects
                num_obj = num_valid = 0
                for obj in self.storage_objects:
                    if not self.is_valid_object(obj):
                        raise ValueError(f"Invalid object in hierarchy: {obj}")
                    num_obj += 1
                    if self.is_valid_object(obj):
