                return num_obj, good_obj
            except (ValueError, Exception) as e:
                if show_warnings:
                    print(f"Warning: {e}")
                return num_obj, 0
        return 0, 0  # If validation is not requested, return 0 for both counts

def next_version(version):
    """
    Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.

    :param version: Version identifier.
    :return: Integer, next version identifier.
    """
    if version.startswith('v'):
        version = version[1:]

    if version:
        # Split the version into release, major, minor components
        parts = version.split('.')

        # Find the last non-zero component
        non_zero_part_index = len(parts) - 1
        while non_zero_part_index >= 0:
            if parts[non_zero_part_index].isdigit():
                break
            non_zero_part_index -= 1

        if non_zero_part_index == -1:
            # If no non-zero component found, return 1
            return 1
        else:
            # Increment the non-zero component by 1
            parts[non_zero_part_index] = str(int(parts[non_zero_part_index]) + 1)
            # Combine the parts back into a version string
            return '.'.join(parts)
    else:
        # If version is empty, return 1
        return 1

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if version.startswith("0"):
        return f"{int(version[1:]) + 1}.0.0"
    else:
        return f"{version}1.0.0"

