    Must deal with both zero-prefixed and non-zero prefixed versions.

    """
    parts = version.split('.')

    if parts[0] == '0':
        parts[0] = '1'
    else:
        parts[0] = str(int(parts[0]) + 1)

    return '.'.join(parts)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if len(version_dirs) == 0:
        raise ValueError('Version directories list is empty.')
    for i, dir_name in enumerate(version_dirs):
        if i == 0 and dir_name != '0':
            raise ValueError(f'First version directory name {dir_name} must be "0".')
        if i == len(version_dirs) - 1 and dir_name != '~':
            raise ValueError(f'Last version directory name {dir_name} must be "~".')
        if not dir_name.isdigit():
            raise ValueError(f'Each version directory name must be a digit.')

def validate_version_inventories(self, version_dirs):
    # Check if version_dirs is an array of version directory names
    if not isinstance(version_dirs, (list, tuple)):
        raise ValueError("version_dirs must be a list or tuple of version directory names")

    # Assume version_dirs is in version sequence (1, 2, 3...)
    version_numbers = list(map(int, version_dirs))

    # Check if the first version is 1
    if version_numbers[0] != 1:
        raise ValueError("The first version should be 1")

    # Loop through version directories starting from the first version
    for i, version_dir in enumerate(version_dirs):
        # Check if the version directory is valid
        try:
            int(version_dir)
        except ValueError:
            raise ValueError(f"Invalid version directory name: {version_dir}")

        # Check if the version directory is in the sequence
        if version_numbers[i] != i + 1:
            raise ValueError(f"Version directory name is out of sequence: {version_dir}")

        # Add the version directory to the set of version directories
        self.version_directories.add(version_dir)

def validate_version_inventories(version_dirs: List[str]) -> None:
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    for i, version_dir in enumerate(version_dirs):
        try:
            packaging.specifiers.SpecifierSet(version_dirs[i])
        except InvalidSpecifier as error:
            tmpl = (
                "version_dirs[{i}] must be a valid version specifier; {error}"
            )
            raise DistributionError(tmpl.format(i=i, error=error))
        else:
            if i > 0 and packaging.specifiers.SpecifierSet(version_dirs[i-1]) > packaging.specifiers.SpecifierSet(version_dirs[i]):
                tmpl = (
                    "version dirs [{i+1}] must not precede version dirs [{i}], "
                    "both are version specifiers"
                )
                raise DistributionError(tmpl.format(i=i+1, i=i))

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    namashe_files = ["Namaste"]
    for file in namashe_files:
        if file in path:
            root = path.split(File_PATH_NAME_NAMASTE, 1)
            if len(root) != 2:
                return "cannot determine root directory"
            if root[0] == "":
                return "root directory is empty"
            if len(root[1]) == 0:
                return "object directory is empty"
            if root[1] == File_PATH_NAME_NAMASTE:
                return "object directory"
            if root[1] == File_PATH_NAME_NAMASTE + File_PATH_NAME_ROOT:
                return "root directory"
            return "unknown root directory"
    return "unknown directory"

def find_path_type(path):
    if not os.path.exists(path):
        return "path does not exist"

    try:
        content = BytesIO(open(path, 'rb').read())
        namaste_pattern = re.compile(r'^0=(namaste\s+file\s+?)\s+$', re.IGNORECASE)
        if namaste_pattern.match(content.getvalue().decode('utf-8')):
            return 'root'
        content = BytesIO(open(path, 'rb').read())
        object_pattern = re.compile(r'^ scarcity=(oryam|static|transient|on_demand)\s+(rendered|not_rendered|remote)\s+link-time|environment-time|\s*$', re.IGNORECASE)
        if object_pattern.match(content.getvalue().decode('utf-8')):
            return 'object'
        content = BytesIO(open(path, 'rb').read())
        file_pattern = re.compile(r'^object_type=\w+\s+files\s+active(?: olarak)?$', re.IGNORECASE)
        if file_pattern.match(content.getvalue().decode('utf-8')):
            return 'file'
        return 'unknown'
    except Exception as e:
        return f"error reading path: {e}"

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if not path.startswith('0='):
        return "Invalid path format. It should start with '0='."

    try:
        path = path[2:]
        if path.startswith('/'):
            return 'root'
        elif path.startswith(b'ocfl:object'):
            return 'object'
        elif path.startswith(b'ocfl:file'):
            return 'file'
        else:
            return "Unknown file type."
    except Exception as e:
        return f"An error occurred: {e}"

