def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    """
    merged_nodes = {}
    for key, value in nodes:
        if key in merged_nodes:
            if isinstance(value, dict) and isinstance(merged_nodes[key], dict):
                merged_nodes[key] = deep_merge_nodes([(key, merged_values), (key, value)])
            elif isinstance(value, (int, str)) or (isinstance(value, (list, tuple)) and all(isinstance(v, (int, str)) for v in value)):
                if isinstance(merged_nodes[key], (int, str)) or isinstance(merged_nodes[key], (list, tuple)):
                    differences = list(set(merged_nodes[key]) | set(value))
                    if differences:
                        if isinstance(merged_nodes[key], (int, str)):
                            merged_nodes[key] = value
                        elif isinstance(merged_nodes[key], (list, tuple)):
                            merged_nodes[key] = differences
            else:
                # If we reach this point, it means we have other types of values
                # that don't support deep merging. In this case, we only take the value
                # from the second node, as it is the last one in the list.
                merged_nodes[key] = value
        else:
            merged_nodes[key] = value

    nodes = list(merged_nodes.items())
    return nodes

def deep_merge_nodes(nodes):
    # Dictionary to store merged values keyed by their string representation
    merged_dict = dict()

    for key, value in nodes:
        # Convert boolean and integer values to string representations
        if isinstance(value, bool):
            value_str = str(value).lower()
        elif isinstance(value, int):
            value_str = str(value)
        else:
            value_str = value.to_yaml_string()

        if value_str in merged_dict:
            # Add existing value to the current merged dict
            if isinstance(merged_dict[value_str], list) and isinstance(value, list):
                merged_dict[value_str].extend(value)
            elif isinstance(merged_dict[value_str], set) and isinstance(value, set):
                merged_dict[value_str].update(value)
            elif isinstance(merged_dict[value_str], dict) and isinstance(value, dict):
                merged_dict[value_str].update(value)
            else:
                merged_dict[value_str] = [merged_dict[value_str], value]
        else:
            # Add new value to the merged dict
            merged_dict[value_str] = value

    return list(merged_dict.values())

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    """
    result = defaultdict(lambda: [])

    for key, value in nodes:
        if isinstance(value, MappingNode):
            result[key].append(value)
        else:
            for val in result[key]:
                val.append(value)

    merged_nodes = []
    for key, values in result.items():
        for val in values:
            item = Node()
            item.tag = key.tag
            item.value = val.value
            merged_nodes.append(item)

    return merged_nodes

