def parse_subparser_arguments(unparsed_arguments, subparsers):
    argument_parsers = subparsers.items()
    results = {}
    remaining_arguments = []
    for parser_name, parser in argument_parsers:
        result = parser.parse_known_args(unparsed_arguments)
        results[parser_name] = result[0]
        remaining_arguments.extend(result[1])
    return results, remaining_arguments

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    namespace = None
    remaining_arguments = []
    for argument in unparsed_arguments:
        for subparser_name, subparser in subparsers.items():
            try:
                subparser_actions = subparser._get_parser()._actions
                if argument in [action.dest for action in subparser_actions]:
                    if namespace is None:
                        namespace = subparser.parse_known_args(argument.split())[0]
                    else:
                        namespace.update(subparser.parse_known_args(argument.split())[0])
                remaining_arguments.append(argument)
                break
            except AttributeError:
                # The subparser does not support argument parsing,
                # treat it as a normal string argument.
                namespace = argparse.Namespace()
                namespace.__dict__.update({argument: argument})
                remaining_arguments.append(argument)
    return namespace, remaining_arguments

