def deep_merge_nodes(nodes):
    from ruamel.yaml.nodes import ScalarNode, MappingNode

    merged_options = []
    encountered_keys = set()

    for node_key, child_node in nodes:
        if isinstance(child_node, MappingNode):
            if node_key.key not in encountered_keys:
                encountered_keys.add(node_key.key)
                merged_options.append((node_key, deep_merge_nodes(child_node.items())))
            else:
                child_node_pair = next((pair for pair in merged_options if pair[0] == node_key.key), None)
                if child_node_pair is not None:
                    old_child_node_child_map = child_node_pair[1]
                    child_node.children.update(old_child_node_child_map)
                    merged_options.append((node_key, child_node))
