def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url or not url_args:
        return url

    new_url = url

    for arg_key, arg_value in six.iteritems(url_args):
        arg_match = re.search(arg_key + '(.*?)', new_url)
        if arg_match:
            new_url = new_url.replace(arg_match.group(0), arg_value)

    return new_url

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    # Define a regex pattern to match the URL arguments
    url_regex = r'{[a-zA-Z0-9\_]+}'

    # Replace the URL arguments in the URL with their corresponding values from args
    for match in re.findall(url_regex, url):
        variable = re.sub("{|}", "", match)
        if variable in url_args:
            url = re.sub(match, str(url_args[variable]), url)

    return url

def _replace_url_args(self, url, url_args):
    """Replace any custom string URL items with values in args"""

    url_parts = urllib.parse.urlparse(url)
    path = url_parts.path
    query = urllib.parse.parse_qs(url_parts.query)

    custom_args = {k: v[0] for k, v in url_args.items() if k in query}

    for key, value in custom_args.items():
        path = path.replace(key, value)

    new_parts = url_parts._replace(path=path, query=urlparse.urlencode(query, doseq=True))
    return urllib.parse.urlunparse(new_parts)

