def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    result = ""
    if padding is not None:
        result = str(number).zfill(padding)
    else:
        while number > 0:
            result = alphabet[number % len(alphabet)] + result
            number //= len(alphabet)
    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """

    def find_digit(number):
        for i, digit in enumerate(reversed(alphabet)):
            if number >= len(alphabet) ** i:
                return i

    if padding is not None:
        digits = [find_digit(number)] * padding
    else:
        digits = [find_digit(number) for _ in range(len(alphabet))]

    result = ''.join(alphabet[digit] for digit in digits)
    if padding is not None and len(result) < padding:
        result = '0' * (padding - len(result)) + result

    return result

