    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = os.name
    if platform == 'posix':
        import shlex
        return shlex.split(s)
    elif platform == 'nt':
        import re
        def fix_windows_quotes(line):
            # This is a very simple approach to dealing with Windows '\\'
            # quoted strings.
            # We match any whitespace that's not part of an opening """
            # and replace it with LiteralWhitespace. This assumes only literal
            # whitespace may be used for argument quoting.
            return re.sub(r'\w\s', 'LiteralWhitespace', line)

        return shlex.split(fix_windows_quotes(s))
    else:
        raise ValueError("Unsupported platform: %s - defaulting to POSIX." % platform)

