    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """

    if platform not in ['this', 1, 0]:
        raise ValueError("Invalid platform value. Use 'this' for auto detection, 1 for POSIX, 0 for Windows/CMD.")

    use_posix = platform == 1 or (platform == 'this' and re.search(r'^\[[^\]]+\]$', s))
    if use_posix:
        re_pattern = r'(?:"([^"]+)")|([^ ]+)'
    else:
        if platform == 'this':
            if re.search(r'\r', s) or re.search(r'\n', s):
                re_pattern = r'(?:"([^"]+)"|([^ ]+)|\r|\n)'
            else:
                re_pattern = r'(?:"([^"]+)"|([^ ]+))'
        else:
            re_pattern = r'(?:"([^"]+)"|([^ ]+))'

    parts = re.split(re_pattern, s)
    return parts

def add_ignored(ignored):
    """
    Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.
    """
    def git(args, error_message, cwd=os.getcwd(), **error_kwargs):
        output, status = subprocess.run(args, shell=True, cwd=cwd, capture_output=True, text=True)
        if status != 0:
            error_kwargs['output'] = output
            error_kwargs['directory'] = cwd
            raise subprocess.CalledProcessError(error_message, **error_kwargs)
        return output.strip()

    ignored_files = git('git ls-files --exclude-standard', 'Failed to find ignored files')
    simplified_files = [file for file in ignored_files.split() if file in ignored]

    return ', '.join(simplified_files)

