def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    name, default = matcher.group('var'), matcher.group('default')
    if name not in os.environ:
        raise EnvironmentError("Environment variable '{0}' is not defined.".format(name), name)
    value = os.environ[name]
    if default is not None and value != default:
        return value
    try:
        return int(value)
    except ValueError:
        if ":" in value:
            token = value.split(":")
        else:
            token = value.split(".")
        if "-" in token:
            return float(token[0])
        try:
            return float(token[0]) + float(token[1])
        except ValueError:
            return float(token[0])
    return value

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    if ':' in matcher:
        name, default = matcher.split(':')
    else:
        name = matcher
        default = None

    if name not in os.environ:
        if default:
            return default
        raise EnvironmentError(f"Environment variable '{name}' not found")

    value = os.environ[name]
    return value

