def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    ifroots = set()
    for (child, _, parent) in graph:
        ifgraph[child].subClassesOf(graph[parent], prop):
            if roots is not None:
                roots.add(child)
            elif child not in ifroots:
                ifroots.add(child)
    return ifroots

def find_roots(graph, prop, roots=None):
    if roots is None:
        roots = set()
    for child, parent in graph.predicate_objects(prop):
        if parent not in roots:
            roots.add(parent)
            find_roots(graph, prop, roots)
    return roots

def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    if not roots:
        roots = set(Node(node) for node in graph.get_children(graph.graph.keys()[-1]))
    todo = deque(roots)
    done = set(roots)
    while todo:
        node = todo.popleft()
        if node in done:
            continue

        parent = graph.get_parents(node)
        if not parent:
            done.add(node)
            continue

        new_roots = parent - done
        if new_roots:
            todo.extend(new_roots)
            done.update(new_roots)

    return roots

def find_roots(graph, prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    if roots is None:
        roots = set()

    for node in graph.objects(None, prop):
        if node not in roots:
            find_roots(graph, prop, roots | {node})

    return roots

