def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""

    def handle_type(obj):
        # Note: We use `try-except` to handle both Unicode and non-Unicode objects
        try:
            return yaml.dump(obj, explicit_start=True, allow_unicode=True, Dumper=Dumper)
        except TypeError as e:
            if isinstance(e, unicode):  # Py2
                return str(e)
            else:  # Py3
                return str(e).encode('utf-8')

    return handle_type(obj)

