    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    configs = defaultdict(dict)
    error_log_records = []
    for filename in config_filenames:
        config_path = os.path.join(_get_config_dir(), filename)
        try:
            if filename.endswith('.toml'):
                with open(config_path) as fd:
                    raw_config = fd.read()
                process_config(toml.loads(raw_config), configs)
            elif filename.endswith('.yaml'):
                with open(config_path) as fd:
                    raw_config = fd.read()
                process_config(yaml.safe_load(raw_config), configs)
            else:
                raise ValueError('Unknown file type: {}'.format(filename))
        except SyntaxError as e:
            error_log_records.append(logging.LogRecord(
                name=__name__,
                level=logging.ERROR,
                msg=f"Syntax error in {filename}: {str(e)}",
                exc_info=True,
                module=os.path.basename(filename)
            ))
        except Exception as e:
            error_log_records.append(logging.LogRecord(
                name=__name__,
                level=logging.ERROR,
                msg=f"Error loading {filename}: {str(e)}",
                exc_info=True,
                module=os.path.basename(filename)
            ))

    if overrides:
        for key, override in overrides.items():
            configs[key].update(override)

    if resolve_env:
        for config_dict in configs.values():
            for key, value in config_dict.items():
                if isinstance(value, dict) and value.get('env'):
                    config_dict[key] = os.getenv(value['env'], value)

    return configs, error_log_records

def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is None:
            return cls.HANDLERS

        if not isinstance(protocol_version, tuple):
            raise TypeError("Protocol version must be passed as a tuple")

        if protocol_version not in cls.HANDLERS:
            return {}

        return {protocol_version: cls.HANDLERS[protocol_version]}

def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """

        try:
            protocol_version_tuple = tuple(protocol_version)
        except TypeError:
            raise TypeError("Protocol version must be passed in a tuple")

        protocol_handlers = {}
        for handler in cls.handlers:
            if isinstance(handler, cls.ProtocolHandler):
                protocol_version = handler.supported_protocol_version
                if protocol_version is None or protocol_version in protocol_version_tuple:
                    protocol_handlers[protocol_version] = handler

        if protocol_version is not None:
            protocol_handlers[protocol_version] = handler

        return protocol_handlers

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    handlers = {}
    for handler in cls.__subclasses__():
        if hasattr(handler, '_protocol_version'):
            protocol = handler._protocol_version
            if protocol_version is None or protocol <= protocol_version:
                handlers[protocol] = handler

    if protocol_version is not None:
        return handlers.get(protocol_version, {})
    else:
        return handlers

