def _verify(iface, candidate, tentative=False, vtype=None):
    if tentative and not hasattr(candidate, 'providedBy'):
        raise Invalid(f"The candidate does not provide the interface {iface}")

    implemented_interfaces = iface.providedBy(candidate)
    if implemented_interfaces != iface:
        raise Invalid(f"Tentative provided by {candidate}, but not implemented by it: {implemented_interfaces}")

    all_methods = set(iface)
    if implemented_interfaces:
        candidate_methods = set(candidate.getAttributes(True) + dir(candidate))
        missing_methods = all_methods - candidate_methods
        if missing_methods:
            if len(missing_methods) > 1:
                raise Invalid(f"The candidate does not define all necessary methods: {missing_methods}")
            elif len(missing_methods) == 1:
                raise Invalid(f"The candidate does not define the required method {missing_methods.pop()}")

    all_attributes = set(iface)
    candidate_attributes = set(candidate.getAttributes(True))
    missing_attributes = all_attributes - candidate_attributes
    if missing_attributes:
        if len(missing_attributes) > 1:
            raise Invalid(f"The candidate does not define all necessary attributes: {missing_attributes}")
        elif len(missing_attributes) == 1:
            raise Invalid(f"The candidate does not define the required attribute {missing_attributes.pop()}")

    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    interface_impl = iface.providedBy(candidate)
    interface_provider = interface.providedBy(candidate)

    # Making sure the candidate claims that it provides the interface using iface.providedBy
    if interface_impl and not tentative:
        if not interface_provider:
            raise zope.interface.Invalid("Minimum implementation necessary for {iface}".format(iface=iface))

    # Making sure the candidate defines all the necessary methods
    for meth in iface.providedBy(interface):
        if not hasattr(candidate, meth.im_func.__name__):
            raise zope.interface.Invalid("Interface '+iface+' requires method '+meth+' that is not present in '+candidate+'.")

    # Making sure the methods have the correct signature (to the extent possible)
    for meth in iface.providedBy(interface):
        if getattr(candidate, meth.im_func.__name__).__defaults__ is not None:
            num_default = len(getattr(candidate, meth.im_func.__name__).__defaults__)
            for idx, arg_name in enumerate(getattr(meth, 'args')):
                if arg_name in getattr(candidate, meth.im_func.__name__).__defaults__:
                    if len(getattr(candidate, meth.im_func.__name__)[idx]) != num_default:
                        raise zope.interface.Invalid("Method '+meth+' in '+candidate+' has an extra argument.")
                else:
                    if getattr(candidate, meth.im_func.__name__)[idx] != None:
                        raise zope.interface.Invalid("Method '+meth+' in '+candidate+' has an unexpected argument.")
        if getattr(candidate, meth.im_func.__name__).__kwdefaults__ is not None:
            for arg_name in getattr(meth, 'kwattrs'):
                if callable(getattr(candidate, meth.im_func.__name__)[arg_name]):
                    kwargs = getattr(candidate, meth.im_func.__name__)(**getattr(candidate, meth.im_func.__name__).__kwdefaults__)
                    meth_params = inspect.signature(getattr(meth, 'func')).parameters
                    for k in kwargs.keys():
                        if k not in meth_params:
                            raise zope.interface.Invalid("Method '+meth+' in '+candidate+' has an unexpected keyword argument.")
                        if k in m_params and m_params[k].default != inspect.Parameter.empty:
                            if getattr(candidate, meth.im_func.__name__)[k] != kwargs[k]:
                                raise zope.interface.Invalid("Method '+meth+' in '+candidate+' has a mismatched keyword argument.")
                        else:
                            if getattr(candidate, meth.im_func.__name__)[k] != kwargs[k]:
                                raise zope.interface.Invalid("Method '+meth+' in '+candidate+' has an unexpected keyword argument.")
                else:
                    if getattr(candidate, meth.im_func.__name__)[arg_name] != None:
                        raise zope.interface.Invalid("Method '+meth+' in '+candidate+' has an unexpected keyword argument.")

    # Checking for the candidates to define all the necessary attributes
    if tentative:
        return True
    for attr in iface.providedBy(interface):
        if not hasattr(candidate, attr):
            raise zope.interface.Invalid("Interface '+iface+' requires attribute '+attr+' that is not present in '+candidate+'.")

    return True

def verifyObject(iface, candidate, tentative=False):
    # Check if thecandidate claims to provide the interface
    if tentative or not isinstance(candidate, iface.providedBy):
        return False

    # Check if all necessary methods are defined
    if not iface.implementedBy(candidate):
        return False

    # Check if all necessary attributes are defined
    if not hasattr(candidate, iface.implementedBy()[0]):
        return False

    # Check if the methods have the correct signature if possible
    for name, method in iface.allMethods():
        if not hasattr(candidate, name):
            return False
        signature = inspect.signature(candidate.__getattribute__(name))
        if signature != inspect.signature(iface.__getattribute__(name)):
            return False

    return True

class ConflictingNames(Exception):
    pass

def _checkConflictingNames(interfaces):
    names = {}
    for interface in interfaces:
        for name in interface:
            if name in names:
                otherInterface = names[name]
                parent = _commonParent(interface, otherInterface)
                if parent is None or name not in parent:
                    raise ConflictingNames("%s conflicts with %s over %s" % (
                            interface, otherInterface, name))
            names[name] = interface

