            except exceptions.InferenceError:
                pass
        return None

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Attempt to find the metaclass in the explicit argument
    if explicit_mc is not None:
        return explicit_mc

    # Iterate through the class bases to find an explicit metaclass
    for base in bases:
        if hasattr(base, '_metaclass'):
            return base._metaclass
        if hasattr(base, '__metaclass__'):
            return base.__metaclass__

    # If no explicit metaclass is found, return None
    return None

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    for base in bases:
        if explicit_mc is None:
            try:
                context = base.module
                for baseobj in base.infer(context=context):
                    if isinstance(baseobj, ClassDef) and baseobj.hide:
                        explicit_mc = baseobj._metaclass
                        break
            except exceptions.InferenceError:
                pass

    if explicit_mc:
        return explicit_mc

    return bases[0].__class__

