def isoparse(self, dt_str):
    if not dt_str:
        return None
    d = dt_str.replace('+', ' ')
    date_part, time_part = d.split(' ')
    date = date_part.split('-')
    year, month, day = map(int, date)
    time = time_part.split(':')
    hour, minute, second = map(int, time)
    if time_part.lower().endswith('.'):
        microsecond = int(time_part.replace('.', '').ljust(6, '0'))
    else:
        microsecond = 0
    return datetime(year, month, day, hour, minute, second, microsecond, timezone.utc)

def string_to_datetime(date):
    """Return a datetime.datetime instance with tzinfo."""
    if date is None:
        return None
    if isinstance(date, datetime.datetime):
        if not date.tzinfo:
            date = date.replace(tzinfo=timezone.utc)
        return date
    if isinstance(date, list):
        date = 'T'.join(date)
    if isinstance(date, basestring):
        if len(date) <= len('2000-01-01'):
            return datetime.datetime.strptime(date, '%Y-%m-%d')
        else:
            try:
                parsed = isodate.parse_datetime(date)
            except ValueError:
                # e.g. '2012-01-10 12:13:14Z' becomes '2012-01-10T12:13:14Z'
                parsed = isodate.parse_datetime(
                    re.sub('(\d)\s(\d)', r'\1T\2', date)
                )
            if not parsed.tzinfo:
                parsed = parsed.replace(tzinfo=timezone.utc)
            return parsed
    raise ValueError("date not a parsable string")

