def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    # What if the datetime is naive? Convert it to UTC and then back to local timezone
    if not dt.tzinfo:
        return dt.replace(tzinfo=timezone.utc).astimezone(localtime()).strftime('%Y-%m-%d %H:%M:%S')
    # Otherwise, just convert to local timezone
    return dt.astimezone(localtime()).strftime('%Y-%m-%d %H:%M:%S')

