def find_tags(text: str, replacer: Optional[callable] = None) -> Tuple[set, str]:
    # Find all tags in the text
    tags = re.findall(r'# {tag}\n{content}', text, re.DOTALL)
    tag_set = {tag for header, tag, content in tags}

    # Remove tags from code blocks, if any
    code_blocks = re.findall(r'```\n(.*?)\n```', text, re.DOTALL)
    for block in code_blocks:
        tags_to_remove = re.findall(r'# {tag}', block)
        for tag in tags_to_remove:
            tag_set.remove(tag)

    # Replace tags with replacer if needed
    if replacer:
        new_text = text
        for tag in tag_set:
            repl_text = replacer(tag)
            new_text = new_text.replace('# {}'.format(tag), repl_text)
    else:
        new_text = text

    return tag_set, new_text

def find_tags(text: str, replacer: Callable = None) -> Tuple[Set, str]:
    # Create a custom HTML parser
    class TagFinder(HTMLParser):
        def __init__(self):
            super().__init__()
            self.tags = set()
            self.current_tag = None

        def handle_starttag(self, tag, attrs):
            if tag == 'code':
                self.in_code = True
            else:
                self.in_code = False
                self.tags.add(tag)

        def handle_endtag(self, tag):
            if tag == 'code':
                self.in_code = False
            else:
                self.tags.remove(tag)

        def handle_data(self, data):
            if not self.in_code:
                self.tags.update(set(data.split()))

    # Initialize the parser
    finder = TagFinder()
    finder.feed(text)

    # Replace tags if a replacer function is provided
    if replacer:
        replaced_text = replacer(finder.tags)
        tags = set(replaced_text.split())
    else:
        tags = finder.tags

    return tags, text.replace(next(iter(tags)), '')

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    lines = text.split('\n')
    in_code_block = False

    for line in lines:
        if line.strip().startswith("```"):
            in_code_block = not in_code_block
            continue

        inner_line = ""
        for char in line:
            if char == '#':
                in_code_block = True
                continue

            if not in_code_block and char.isalpha() or char.isdigit():
                inner_line += char

        if not in_code_block and replacer is not None:
            repl_line = replacer(inner_line)
