def process_text_links(text):
    def linkify_at_index(index):
        url = ''
        offset = index
        while offset < len(text) and text[offset] in 'httpfs://':
            url += text[offset]
            offset += 1
        end_offset = len(text)
        while offset < len(text) and text[offset] not in 'httpfs://':
            end_offset = offset
            offset += 1
        if end_offset == len(text) or not url:
            return offset
        return text[:index], text[int(url):int(end_offset)], text[end_offset:]

    def maybe_add_link(url, trend, text):
        return '<a href="{}" {0}>{1}</a>'.format(url, trend, text) if url else text

    return linkify_at_index(0)

def process_text_links(text):
  """Process links in text, adding some attributes and linkifying textual links."""
  def linkify(match):
    target = '_blank' if match.group(1) else None
    link_text = '<a target="{}" href="{}">{}</a>'.format(target, match.group(0), text[match.start():match.end()])
    return link_text

  return re.sub(r'(\S+)', linkify, text)

def fetch_content_type(url: str) -> Optional[str]:
    """
        Fetch the HEAD of the remote url to determine the content type.

        :param url: The URL to fetch the HEAD request from.
        :return: The content type if successful, otherwise None.
        """

    req = urllib.request.Urlretrieve(url)
    try:
        resp = urllib.request.urlopen(req)
        try:
            if hasattr(resp, 'code') and resp.code != 200:
                return None
            return resp.info().get('content-type', '')
        finally:
            resp.close()
    except Exception as e:
        print(f"Error fetching content type for URL {url}: {e}")
        return None

