def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type.

    :param url: The URL to fetch the content type from
    :return: The content type of the remote URL
    """
    scheme, netloc, path, query, fragment = urllib.parse.urlsplit(url)
    if not scheme in ('http', 'https', 'ftp', 'ftps'):
        return None
    try:
        req = urllib.request.Request(url, method='HEAD')
        req.add_header('Host', netloc)
        resp = urllib.request.urlopen(req)
        if resp.status_code != 200 and scheme not in ('ftp', 'ftps'):
            return None
        return resp.info().get('content-type', '')
    except Exception as e:
        print(f"Error fetching content type: {e}")
        return None

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD request of the remote url to determine the content type.
    """
    if not url.startswith(('http://', 'https://', 'ftp://')):
        raise ValueError("Invalid URL")

    try:
        response = urllib.request.urlopen(url, method='HEAD')
        content_type = response.info().get('Content-Type')
        return content_type
    except Exception as e:
        print(f"Error fetching content type: {e}")
        return None

