def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if document_path is None:
        document_path = "/.well-known/nodeinfo"

    document_url = f"{url}{document_path}"

    response = requests.get(document_url)

    if response.status_code == 200:
        try:
            root = ET.fromstring(response.text)
            version = root.find(".//version").text
            protocols = [protocol.text for protocol in root.findall(".//protocols/protocol")]
            return {
                "version": version,
                "protocols": protocols,
            }
        except ET.ParseError:
            raise ValueError("Failed to parse NodeInfo document")
    else:
        raise ValueError(f"Failed to retrieve NodeInfo document: status code {response.status_code}")

