def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("spec_content argument must be supplied")

    try:
        spec = yaml.safe_load(spec_content)
    except yaml.YAMLError as e:
        raise IRValidatorException("Invalid spec file: {}".format(e))

    required_fields = set()  # Set of all required fields
    for field in spec.values():
        if field.get('required'):
            required_fields.add(field.get('name'))

    missing_fields = required_fields.difference(spec.keys())
    if missing_fields:
        missing_field_str = ', '.join(missing_fields)
        raise IRValidatorException(f"Missing required fields in spec: {missing_field_str}")

    return spec

