    if 'include' in parser_dict:
        included_directive = parser_dict['include']
        if included_directive in self.include_directives:
            included_directive_path = self.include_directives[included_directive]
            with open(included_directive_path, 'r') as file:
                included_content = file.read().strip()
                included_dict = eval(included_content)
                parser_dict.update(included_dict)
        else:
            raise ValueError(f"Include directive '{included_directive}' not found.")

