def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            raise errors.InvalidSchemeError('Unable to resolve default for non-Option type')

        # if there is a default set, add it to the defaults dict
        if not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default

        # if we have a dict option, build the defaults for its scheme.
        # if any defaults exist, use them.
        if isinstance(arg, DictOption):
            if arg.scheme:
                try:
                    b = arg.scheme.build_defaults()
                    if b:
                        defaults[arg.name] = b
                except errors.InvalidSchemeError as e:
                    # If the scheme is invalid, raise the exception to propagate it.
                    raise e
    return defaults

class _BaseOpt:
    name: str
    default: Any

class DictOption(_BaseOpt):
    scheme: Optional['Scheme']

class NoDefault:
    pass

class errors:
    InvalidSchemeError: Exception

class Scheme:
    args: List[_BaseOpt]
    def __init__(self, args: List[_BaseOpt]):
        self.args = args

    def build_defaults(self) -> Dict[str, Any]:
        defaults = {}
        for arg in self.args:
            if not isinstance(arg, _BaseOpt):
                raise errors.InvalidSchemeError('Unable to build default for non-Option type')

            # if there is a default set, add it to the defaults dict
            if not isinstance(arg.default, NoDefault):
                defaults[arg.name] = arg.default

            # if we have a dict option, build the defaults for its scheme.
            # if any defaults exist, use them.
            if isinstance(arg, DictOption):
                if arg.scheme:
                    b = arg.scheme.build_defaults()
                    if b:
                        defaults[arg.name] = b
        return defaults

