    if min_value > max_value:
        raise ValueError("'min_value' must be less than or equal to 'max_value'.")

    return args

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for arg in args:
        if arg["type"] not in ["int", "float"]:
            raise ValueError("All arguments must be of type int or float")
        if "min" not in arg or "max" not in arg:
            raise ValueError("All arguments must have 'min' and 'max' keys")

        min_val = arg["min"]
        max_val = arg["max"]

        if not isinstance(min_val, (int, float)):
            raise ValueError("Min value must be of type int or float")
        if not isinstance(max_val, (int, float)):
            raise ValueError("Max value must be of type int or float")

        if min_val > max_val:
            raise ValueError("Min value must be less than or equal to max value")

    return args

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    if not type_name or not option_name or not spec_option:
        raise ValueError("All arguments are required")

    # Create the complex argument factory based on the spec option description
    if spec_option['type'] == 'int':
        factory = int
    elif spec_option['type'] == 'str':
        factory = str
    elif spec_option['type'] == 'bool':
        factory = bool
    elif spec_option['type'] == 'enum':
        factory = self.get_enum_class(spec_option['enum_type'])
    else:
        raise ValueError(f"Unsupported type: {spec_option['type']}")

    # Construct the complex argument type instance
    if spec_option['required']:
        complex_argobj = factory(**spec_option['kwargs'])
    else:
        complex_argobj = factory(**spec_option['kwargs'], **{option_name: None})

    return complex_argobj

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    nested_vars = {}
    custom_vars = {}
    control_args = {}

    for arg in args:
        if 'nested_arg' in arg:
            nested_vars[arg['nested_arg']] = arg['value']
        elif 'custom_arg' in arg:
            custom_vars[arg['custom_arg']] = arg['value']
        elif 'control_arg' in arg:
            control_args[arg['control_arg']] = arg['value']

    return control_args, nested_vars, custom_vars

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    for arg in args:
        if argument.is_control(arg):
            control_args[arg] = True
        else:
            nested_args[arg] = True

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    for arg in args:
        if arg.startswith('--control-'):
            control_args[arg.split('--control-')[1]] = True
        elif arg.startswith('--nested-'):
            nested_args[arg.split('--nested-')[1]] = True
        elif arg.startswith('--custom-'):
            custom_args[arg.split('--custom-')[1]] = True

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        extra_vars = {}

    for key, value in extra_vars.items():
        if key in vars_dict:
            vars_dict[key] += value
        else:
            vars_dict[key] = value

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not vars_dict:
        return extra_vars if extra_vars is not None else {}
    if extra_vars is None:
        return vars_dict
    extended_vars = {**vars_dict, **extra_vars}
    return extended_vars

def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra_vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if not vars_dict:
            if not extra_vars:
                return vars_dict
            else:
                vars_dict.update({var: val for var, val in extra_vars.items()})
                return vars_dict

        if not extra_vars:
            return vars_dict

        while extra_vars:
            var, val = extra_vars.pop(0)
            if var in vars_dict:
                vars_dict[var] = vars_dict[var] if isinstance(vars_dict[var], list) else [vars_dict[var]]
                vars_dict[var] += [val]
            else:
                vars_dict[var] = val

        return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    if not len(extra_vars):
        output = vars_dict
    else:
        output = {**vars_dict, **extra_vars}
    return Output(output=output)

def merge_extra_vars(vars_dict, extra_vars):
    if extra_vars is None:
        return vars_dict
    if not isinstance(vars_dict, dict):
        raise ValueError("Input must be a dictionary")
    if not isinstance(extra_vars, list):
        raise ValueError("Extra-vars must be a list")
    original_keys = vars_dict.keys()
    extended_keys = set(extra_vars)
    final_dict = {}
    for key in original_keys:
        if key not in extended_keys:
            final_dict[key] = vars_dict[key]
        else:
            final_dict[key] = vars_dict[key] + extra_vars[key]
    return final_dict

