    for opt in self.parser[parser_name]:
        if opt.name in values_dict:
            values_dict[opt.name] = opt.converter(values_dict[opt.name])
    return values_dict

def _convert_non_cli_args(self, parser_name: str, values_dict: dict) -> None:
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    default_parser = getattr(self, f"{parser_name}_parser")
    for opt in self:
        if opt.name in values_dict and opt.default is not None:
            try:
                values_dict[opt.name] = opt.convert(values_dict[opt.name])
            except (ValueError, TypeError):
                logging.error(f"Failed to convert {opt.name}={values_dict[opt.name]} for parser {parser_name}")

