def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import yaml
    with open(plugin_dir + '/manifest.yml', 'r') as file:
        manifest = yaml.safe_load(file)

    plugin_spec = {}
    for key, value in manifest.items():
        if isinstance(value, dict):
            for subkey, subvalue in value.items():
                if isinstance(subvalue, dict):
                    plugin_spec[key + '_' + subkey] = subvalue
                elif isinstance(subvalue, list):
                    plugin_spec[key + '_' + subkey] = subvalue
                else:
                    plugin_spec[key + '_' + subkey] = subvalue
        else:
            plugin_spec[key] = value

    return plugin_spec

